-- ProcEMP — PostgreSQL schema (migration scaffold, mirrors schema.sql).
--
-- This is a hand-maintained PostgreSQL translation of schema.sql (SQLite).
-- tests/test_migration.py enforces table/column parity between the two files,
-- so they must be updated in lockstep.
--
-- Translations applied:
--   PRAGMA foreign_keys = ON        -> dropped (PostgreSQL always enforces FKs)
--   INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--                                        (explicit seq inserts stay allowed)
--   RAISE(ABORT, 'msg') triggers    -> plpgsql procemp_block_mutation() + TG_ARGV[0]
--   REAL                            -> DOUBLE PRECISION (SQLite REAL is 8-byte IEEE)
--
-- Semantics preserved: append-only ledger, immutable pinned transaction
-- fields, WORM sealed folders, frozen benchmark cases. FKs/CHECKs/UNIQUEs
-- are identical. Load with psql on the approved target environment only;
-- see ops_migrate_pg.py and procurement-review/06-deployment-runbook.md §9.

\set ON_ERROR_STOP on

CREATE OR REPLACE FUNCTION procemp_block_mutation() RETURNS trigger AS $body$
BEGIN
  RAISE EXCEPTION '%', TG_ARGV[0];
END;
$body$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS ruleset (
  id             TEXT PRIMARY KEY,
  regime         TEXT NOT NULL,
  version        TEXT NOT NULL,
  effective_from TEXT NOT NULL,
  effective_to   TEXT,
  issuance_ref   TEXT NOT NULL,
  checksum       TEXT NOT NULL,
  approved_by    TEXT NOT NULL,
  approved_at    TEXT NOT NULL,
  note           TEXT,
  UNIQUE (regime, version)
);

CREATE TABLE IF NOT EXISTS rule (
  id          TEXT PRIMARY KEY,
  ruleset_id  TEXT NOT NULL REFERENCES ruleset(id),
  key         TEXT NOT NULL,
  value_json  TEXT NOT NULL,
  section_ref TEXT NOT NULL,
  mode        TEXT NOT NULL DEFAULT '*',
  verified    INTEGER NOT NULL DEFAULT 0,
  note        TEXT,
  UNIQUE (ruleset_id, key, mode)
);

CREATE TABLE IF NOT EXISTS corpus_snapshot (
  id          TEXT PRIMARY KEY,
  version     TEXT NOT NULL,
  regime      TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  checksum    TEXT NOT NULL,
  approved_by TEXT NOT NULL,
  is_active   INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS corpus_chunk (
  chunk_id            TEXT PRIMARY KEY,
  corpus_snapshot_id  TEXT NOT NULL REFERENCES corpus_snapshot(id),
  law                 TEXT NOT NULL,
  issuance_no         TEXT NOT NULL,
  section             TEXT NOT NULL,
  regime              TEXT NOT NULL,
  effective_from      TEXT NOT NULL,
  effective_to        TEXT,
  supersedes          TEXT,
  source_url          TEXT NOT NULL,
  text                TEXT NOT NULL,
  passage_hash        TEXT NOT NULL,
  verified            INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS transition_policy (
  id     INTEGER PRIMARY KEY CHECK (id = 1),
  status TEXT NOT NULL,
  note   TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS proc_tx (
  id                 TEXT PRIMARY KEY,
  number             TEXT UNIQUE NOT NULL,
  regime             TEXT NOT NULL,
  ruleset_id         TEXT NOT NULL REFERENCES ruleset(id),
  ruleset_version    TEXT NOT NULL,
  corpus_snapshot_id TEXT NOT NULL REFERENCES corpus_snapshot(id),
  mode               TEXT NOT NULL,
  award_criterion    TEXT,
  posting_date       TEXT NOT NULL,
  stage              TEXT NOT NULL,
  drafter_id         TEXT,
  legal_basis_note   TEXT,
  created_at         TEXT NOT NULL
);

DROP TRIGGER IF EXISTS proc_tx_no_repin ON proc_tx;
CREATE TRIGGER proc_tx_no_repin
BEFORE UPDATE OF regime, ruleset_id, ruleset_version, corpus_snapshot_id, posting_date ON proc_tx
FOR EACH ROW EXECUTE FUNCTION procemp_block_mutation('pinned transaction fields are immutable');

CREATE TABLE IF NOT EXISTS stage_gate (
  id             TEXT PRIMARY KEY,
  tx_id          TEXT NOT NULL REFERENCES proc_tx(id),
  from_stage     TEXT NOT NULL,
  to_stage       TEXT NOT NULL,
  required_role  TEXT NOT NULL,
  required_count INTEGER NOT NULL DEFAULT 1,
  UNIQUE (tx_id, from_stage, to_stage, required_role)
);

CREATE TABLE IF NOT EXISTS signoff (
  id             TEXT PRIMARY KEY,
  tx_id          TEXT NOT NULL REFERENCES proc_tx(id),
  gate_id        TEXT NOT NULL REFERENCES stage_gate(id),
  signer_id      TEXT NOT NULL,
  signer_role    TEXT NOT NULL,
  method         TEXT NOT NULL,
  signature_hash TEXT NOT NULL,
  document_hash  TEXT NOT NULL,
  signed_at      TEXT NOT NULL,
  UNIQUE (gate_id, signer_id, document_hash)
);

CREATE TABLE IF NOT EXISTS ledger_event (
  seq         BIGINT GENERATED BY DEFAULT AS IDENTITY,
  event_id    TEXT UNIQUE NOT NULL,
  tx_id       TEXT NOT NULL,
  event_type  TEXT NOT NULL,
  actor_id    TEXT NOT NULL,
  actor_role  TEXT NOT NULL,
  payload     TEXT NOT NULL,
  occurred_at TEXT NOT NULL,
  prev_hash   TEXT NOT NULL,
  row_hash    TEXT NOT NULL,
  PRIMARY KEY (seq)
);

DROP TRIGGER IF EXISTS ledger_no_update ON ledger_event;
CREATE TRIGGER ledger_no_update
BEFORE UPDATE ON ledger_event
FOR EACH ROW EXECUTE FUNCTION procemp_block_mutation('ledger is append-only');

DROP TRIGGER IF EXISTS ledger_no_delete ON ledger_event;
CREATE TRIGGER ledger_no_delete
BEFORE DELETE ON ledger_event
FOR EACH ROW EXECUTE FUNCTION procemp_block_mutation('ledger is append-only');

CREATE TABLE IF NOT EXISTS number_sequence (
  type       TEXT NOT NULL,
  unit       TEXT NOT NULL,
  year       INTEGER NOT NULL,
  next_value INTEGER NOT NULL,
  PRIMARY KEY (type, unit, year)
);

CREATE TABLE IF NOT EXISTS issued_number (
  number        TEXT PRIMARY KEY,
  type          TEXT NOT NULL,
  unit          TEXT NOT NULL,
  year          INTEGER NOT NULL,
  ordinal       INTEGER NOT NULL,
  status        TEXT NOT NULL DEFAULT 'ACTIVE',
  issued_at     TEXT NOT NULL,
  void_reason   TEXT,
  void_approver TEXT,
  UNIQUE (type, unit, year, ordinal)
);

CREATE TABLE IF NOT EXISTS document (
  id             TEXT PRIMARY KEY,
  tx_id          TEXT NOT NULL REFERENCES proc_tx(id),
  artifact_class TEXT NOT NULL,
  content_hash   TEXT NOT NULL,
  metadata       TEXT NOT NULL,
  ingested_at    TEXT NOT NULL,
  opening_seq    INTEGER
);

CREATE TABLE IF NOT EXISTS verdict (
  id         TEXT PRIMARY KEY,
  tx_id      TEXT NOT NULL REFERENCES proc_tx(id),
  payload    TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS form_registry (
  code                  TEXT PRIMARY KEY,
  name                  TEXT NOT NULL,
  classification        TEXT NOT NULL,
  category              TEXT NOT NULL,
  applies_to            TEXT NOT NULL,
  required_fields       TEXT NOT NULL,
  official_file_hash    TEXT,
  official_file_version TEXT,
  body_available        INTEGER NOT NULL DEFAULT 0,
  verified              INTEGER NOT NULL DEFAULT 0,
  source                TEXT NOT NULL,
  note                  TEXT
);

CREATE TABLE IF NOT EXISTS draft (
  id              TEXT PRIMARY KEY,
  tx_id           TEXT NOT NULL REFERENCES proc_tx(id),
  form_code       TEXT NOT NULL REFERENCES form_registry(code),
  body            TEXT NOT NULL,
  content_hash    TEXT NOT NULL,
  status          TEXT NOT NULL,
  approved_fields TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  created_by      TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS sealed_folder (
  id                  TEXT PRIMARY KEY,
  tx_id               TEXT NOT NULL REFERENCES proc_tx(id),
  version             INTEGER NOT NULL,
  folder_hash         TEXT NOT NULL,
  attested_chain_head TEXT NOT NULL,
  attested_last_seq   INTEGER NOT NULL,
  content_json        TEXT NOT NULL,
  sealed_at           TEXT NOT NULL,
  sealed_by           TEXT NOT NULL,
  supersedes_seal_id  TEXT,
  supersede_reason    TEXT,
  UNIQUE (tx_id, version)
);

DROP TRIGGER IF EXISTS sealed_folder_no_update ON sealed_folder;
CREATE TRIGGER sealed_folder_no_update
BEFORE UPDATE ON sealed_folder
FOR EACH ROW EXECUTE FUNCTION procemp_block_mutation('sealed folders are immutable; create a superseding version');

DROP TRIGGER IF EXISTS sealed_folder_no_delete ON sealed_folder;
CREATE TRIGGER sealed_folder_no_delete
BEFORE DELETE ON sealed_folder
FOR EACH ROW EXECUTE FUNCTION procemp_block_mutation('sealed folders are immutable');

CREATE TABLE IF NOT EXISTS contract_terms (
  tx_id            TEXT PRIMARY KEY REFERENCES proc_tx(id),
  contract_amount  DOUBLE PRECISION NOT NULL,
  start_date       TEXT NOT NULL,
  completion_date  TEXT NOT NULL,
  ld_rate_per_day  DOUBLE PRECISION,
  ld_cap_ratio     DOUBLE PRECISION,
  approved_by      TEXT NOT NULL,
  approved_at      TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS milestone (
  id              TEXT PRIMARY KEY,
  tx_id           TEXT NOT NULL REFERENCES proc_tx(id),
  sequence        INTEGER NOT NULL,
  name            TEXT NOT NULL,
  due_date        TEXT NOT NULL,
  amount          DOUBLE PRECISION,
  status          TEXT NOT NULL DEFAULT 'PENDING',
  completed_at    TEXT,
  evidence_doc_id TEXT,
  verified_by     TEXT,
  UNIQUE (tx_id, sequence)
);

CREATE TABLE IF NOT EXISTS variation_order (
  id               TEXT PRIMARY KEY,
  tx_id            TEXT NOT NULL REFERENCES proc_tx(id),
  reference        TEXT NOT NULL,
  description      TEXT NOT NULL,
  requested_amount DOUBLE PRECISION,
  reason           TEXT NOT NULL,
  status           TEXT NOT NULL DEFAULT 'DRAFT',
  requested_by     TEXT NOT NULL,
  reviewed_by      TEXT,
  reviewed_at      TEXT,
  created_at       TEXT NOT NULL,
  UNIQUE (tx_id, reference)
);

CREATE TABLE IF NOT EXISTS correction (
  id                TEXT PRIMARY KEY,
  tx_id             TEXT NOT NULL,
  verdict_id        TEXT,
  field_path        TEXT NOT NULL,
  ai_value          TEXT NOT NULL,
  correct_value     TEXT NOT NULL,
  reason            TEXT NOT NULL,
  submitted_by      TEXT NOT NULL,
  submitted_at      TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'PENDING',
  adjudicated_by    TEXT,
  adjudicated_at    TEXT,
  adjudication_note TEXT,
  training_batch_id TEXT
);

CREATE TABLE IF NOT EXISTS citation_feedback (
  id                   TEXT PRIMARY KEY,
  tx_id                TEXT NOT NULL,
  chunk_id             TEXT NOT NULL,
  issue                TEXT NOT NULL,
  note                 TEXT,
  submitted_by         TEXT NOT NULL,
  submitted_at         TEXT NOT NULL,
  status               TEXT NOT NULL DEFAULT 'OPEN',
  resolved_by          TEXT,
  resolved_at          TEXT,
  resolved_snapshot_id TEXT
);

CREATE TABLE IF NOT EXISTS benchmark_case (
  id           TEXT PRIMARY KEY,
  case_id      TEXT NOT NULL UNIQUE,
  slice_name   TEXT NOT NULL,
  input_json   TEXT NOT NULL,
  expected_json TEXT NOT NULL,
  source_ref   TEXT NOT NULL,
  frozen_by    TEXT NOT NULL,
  frozen_at    TEXT NOT NULL
);

DROP TRIGGER IF EXISTS benchmark_no_update ON benchmark_case;
CREATE TRIGGER benchmark_no_update
BEFORE UPDATE ON benchmark_case
FOR EACH ROW EXECUTE FUNCTION procemp_block_mutation('benchmark cases are frozen and immutable');

DROP TRIGGER IF EXISTS benchmark_no_delete ON benchmark_case;
CREATE TRIGGER benchmark_no_delete
BEFORE DELETE ON benchmark_case
FOR EACH ROW EXECUTE FUNCTION procemp_block_mutation('benchmark cases are frozen and immutable');

CREATE TABLE IF NOT EXISTS training_batch (
  id                    TEXT PRIMARY KEY,
  created_at            TEXT NOT NULL,
  created_by            TEXT NOT NULL,
  correction_count      INTEGER NOT NULL,
  base_training_set     TEXT NOT NULL,
  training_snapshot_hash TEXT NOT NULL,
  status                TEXT NOT NULL DEFAULT 'CREATED',
  candidate_version_id  TEXT
);

CREATE TABLE IF NOT EXISTS model_version (
  id                    TEXT PRIMARY KEY,
  version               TEXT NOT NULL UNIQUE,
  model_type            TEXT NOT NULL DEFAULT 'EXTRACTION',
  training_batch_id     TEXT,
  training_snapshot_hash TEXT,
  corpus_snapshot_id    TEXT,
  q_lora_config_json    TEXT,
  eval_run_id           TEXT,
  eval_score            DOUBLE PRECISION,
  per_slice_json        TEXT,
  status                TEXT NOT NULL DEFAULT 'CANDIDATE',
  approver              TEXT,
  approved_at           TEXT,
  approval_note         TEXT,
  deployed_at           TEXT,
  deployed_by           TEXT,
  rollback_target       TEXT,
  created_at            TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS eval_run (
  id                     TEXT PRIMARY KEY,
  candidate_version_id   TEXT NOT NULL,
  benchmark_snapshot_hash TEXT NOT NULL,
  per_slice_json         TEXT NOT NULL,
  overall_score          DOUBLE PRECISION NOT NULL,
  production_score       DOUBLE PRECISION,
  production_slice_json  TEXT,
  regressions_json       TEXT NOT NULL,
  passed                 INTEGER NOT NULL,
  evaluator              TEXT NOT NULL,
  run_at                 TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS review_item (
  id               TEXT PRIMARY KEY,
  tx_id            TEXT NOT NULL REFERENCES proc_tx(id),
  verdict_id       TEXT NOT NULL REFERENCES verdict(id),
  status           TEXT NOT NULL DEFAULT 'OPEN',
  reason           TEXT NOT NULL,
  priority         TEXT NOT NULL DEFAULT 'NORMAL',
  assigned_to      TEXT,
  created_at       TEXT NOT NULL,
  created_by       TEXT NOT NULL,
  resolved_at      TEXT,
  resolved_by      TEXT,
  resolution       TEXT,
  resolution_note  TEXT,
  UNIQUE (tx_id, verdict_id)
);

CREATE TABLE IF NOT EXISTS review_action (
  id              TEXT PRIMARY KEY,
  review_item_id  TEXT NOT NULL REFERENCES review_item(id),
  tx_id           TEXT NOT NULL REFERENCES proc_tx(id),
  action          TEXT NOT NULL,
  actor_id        TEXT NOT NULL,
  actor_role      TEXT NOT NULL,
  note            TEXT,
  payload_json    TEXT,
  created_at      TEXT NOT NULL
);
